public class ArrayInspectorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            Summary mixed = ArrayInspector.summarize(new int[] {3, 1, 4, 1, 5});
            check("count of five values", 5, mixed.count());
            check("smallest value", 1, mixed.min());
            check("largest value", 5, mixed.max());
            check("mean of five values", 2.8, mixed.mean());

            Summary single = ArrayInspector.summarize(new int[] {7});
            check("single element count", 1, single.count());
            check("single element mean", 7.0, single.mean());

            Summary negatives = ArrayInspector.summarize(new int[] {-5, -1, -3});
            check("min of negatives", -5, negatives.min());
            check("max of negatives", -1, negatives.max());
            check("mean of negatives", -3.0, negatives.mean());

            Summary rounded = ArrayInspector.summarize(new int[] {1, 2});
            check("mean rounds to two decimals", 1.5, rounded.mean());

            Summary empty = ArrayInspector.summarize(new int[] {});
            check("empty array is all zeroes", "Summary[count=0, min=0, max=0, mean=0.0]", empty.toString());
        } catch (Throwable t) {
            broke("summarize", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

