record Summary(int count, int min, int max, double mean) { }

public class ArrayInspector {

    public static Summary summarize(int[] values) {
        if (values.length == 0) {
            return new Summary(0, 0, 0, 0.0);
        }
        int min = values[0];
        int max = values[0];
        long sum = 0;
        for (int value : values) {
            if (value < min) {
                min = value;
            }
            if (value > max) {
                max = value;
            }
            sum += value;
        }
        double mean = Math.round(sum * 100.0 / values.length) / 100.0;
        return new Summary(values.length, min, max, mean);
    }
}
